#!/usr/bin/env python3
"""Seed ~20 evergreen space / astronomy topics for the space channel.

Same contract as seed_ocean_topics.py: every topic carries real source
text so the LLM research stage has substance to work with. This runs in the
FIRST ytauto-cycle-space build (before the state artifact exists).

Run: .venv/bin/python tools/seed_space_topics.py
"""
import subprocess
import sys

TOPICS = [
    ("Voyager 1: the farthest human object, still phoning home", "https://en.wikipedia.org/wiki/Voyager_1",
     "Launched 5 September 1977, Voyager 1 flew past Jupiter (1979) and Saturn (1980), then kept going. On 14 February 1990, from about 6 billion kilometres, it turned its camera back and took the 'Pale Blue Dot' — Earth as 0.12 of a pixel. It crossed into interstellar space on 25 August 2012, the first human-made object to do so, and now sits over 25 billion km away: a command sent today takes about 23 hours to arrive. Its plutonium batteries will fade in the 2030s, but the Golden Record — 115 images, greetings in 55 languages, sounds of Earth — will drift on for millions of years."),
    ("Pale Blue Dot: the photo Carl Sagan asked for", "https://en.wikipedia.org/wiki/Pale_Blue_Dot",
     "In 1990, engineers let Voyager 1's camera rotate for one last look at home. Earth came out as a 0.12-pixel speck caught in a scatter of sunlight, about 6 billion km away. Carl Sagan turned the image into an argument: everyone who ever lived did their choosing, loving and suffering on that mote — 'the Earth is a very small stage in a vast cosmic arena'. The camera was switched off permanently two days later to save power for the craft's instruments in deep space."),
    ("M87*: the first picture of a black hole", "https://en.wikipedia.org/wiki/Messier_87_star",
     "On 10 April 2019 the Event Horizon Telescope released humanity's first image of a black hole: the shadow of M87*, 55 million light-years away in the galaxy Messier 87, with 6.5 billion solar masses crammed inside its shadow. Eight radio telescopes on four continents observed in April 2017, their data flown on hard drives to be correlated. The bright ring is glowing gas orbiting at nearly light speed — the bottom of it brighter because it races toward us. The image matched Einstein's century-old predictions almost exactly."),
    ("Sagittarius A*: the black hole at the centre of our own galaxy", "https://en.wikipedia.org/wiki/Sagittarius_A*",
     "At the heart of the Milky Way sits Sagittarius A*: about 4 million solar masses in a region smaller than Mercury's orbit. For decades, teams led by Reinhard Genzel and Andrea Ghez tracked individual stars whipping around an invisible point at millions of km/h — the star S2 completes an orbit in 16 years and swings past at over 7,000 km/s. That work won the 2020 Nobel Prize. In May 2022 the EHT collaboration released its image of Sgr A*'s shadow, proving our galaxy hides a monster exactly where the equations said one would be."),
    ("GW150914: the first gravitational wave ever detected", "https://en.wikipedia.org/wiki/GW150914",
     "On 14 September 2015, weeks after upgrades finished, both LIGO detectors felt space stretch and squeeze in unison: a ripple 1.3 billion years old, made when two black holes of 36 and 29 solar masses spiralled together and fused into one of 62. The missing three solar masses were radiated away as pure gravitational-wave energy in a fifth of a second — briefly outshining every star in the observable universe combined, in waves not light. Announced in February 2016, it opened a brand-new sense for astronomy and earned the 2017 Nobel Prize."),
    ("The Crab Pulsar: a dead star spinning 30 times a second", "https://en.wikipedia.org/wiki/Crab_Pulsar",
     "In 1054, court astronomers in Song-dynasty China recorded a 'guest star' bright enough to see in daylight for 23 days. At its spot today is a neutron star — about 20 km wide, denser than an atomic nucleus — spinning roughly 30 times a second and beaming radio pulses like a cosmic lighthouse, the Crab Pulsar. It powers the Crab Nebula, still expanding at 1,500 km/s. Every few years it 'glitches': the crust slips and the spin suddenly jumps, giving physicists rare live data on matter at nuclear density."),
    ("Olympus Mons: the tallest volcano we know of", "https://en.wikipedia.org/wiki/Olympus_Mons",
     "Olympus Mons rises about 21.9 km above the Martian datum — two and a half Everests — and sprawls 600 km wide, roughly the size of Arizona or France, with cliffs up to 8 km high around its base. Mars has no plate tectonics, so a fixed hotspot kept feeding the same shield volcano for hundreds of millions of years until it grew mountain-high. Its caldera alone is 80 km across. From the Martian surface it would extend past the horizon — too large to see whole, its slopes too gentle to notice you are climbing one."),
    ("Jupiter's Great Red Spot: a storm older than your country", "https://en.wikipedia.org/wiki/Great_Red_Spot",
     "The Great Red Spot has been under continuous observation since at least the 1830s — and a similar 'permanent spot' was logged in 1665, though astronomers still argue whether it is the same storm. It is an anticyclone wider than Earth with wind rims racing at up to 430 km/h, and Juno's flybys show its roots reach hundreds of kilometres deep. It has also been shrinking: from around three Earth-diameters a century ago to about 1.3 today. Nobody knows when, or whether, it will fade out entirely."),
    ("Ingenuity: the helicopter that flew first on another world", "https://en.wikipedia.org/wiki/Ingenuity",
     "Designed as a five-flight technology demo, NASA's 1.8 kg Ingenuity made the first powered, controlled flight on another planet on 19 April 2021 — 30 seconds above Jezero Crater, Mars, where the air is thinner than Earth's stratosphere. Rotor blades had to spin five times faster than a Earth helicopter's. It kept flying: 72 flights over three years, scouting routes for the Perseverance rover and proving air travel works on Mars, before a nicked rotor ended the mission in January 2024. Every Mars aircraft since owes it a debt."),
    ("Saturn's rings: Cassini's grand finale", "https://en.wikipedia/wiki/Rings_of_Saturn",
     "For 13 years the Cassini spacecraft studied Saturn; in 2017 it threaded the gap between planet and rings 22 times in the 'Grand Finale' before diving into the clouds to protect moon ecosystems from contamination. Those passes showed the rings are young — perhaps 100-400 million years old, and raining ice into Saturn fast enough that they may vanish in a few hundred million more. Its companion Huygens had already landed on Titan in 2005, the most distant landing ever made, and Cassini found Enceladus spraying ocean water from beneath its ice."),
    ("Total solar eclipses: the 600-million-year sunset of a coincidence", "https://en.wikipedia.org/wiki/Solar_eclipse",
     "The Moon is 400 times smaller than the Sun and 400 times closer, so their discs match to within a percent — total eclipses happen. The match is temporary: the Moon recedes about 3.8 cm a year, and in roughly 600 million years totals will end forever. In the meantime each one is a laboratory: in 1919 Arthur Eddington's eclipse photographs confirmed Einstein's prediction that gravity bends starlight, overnight making the unknown physicist world-famous. During totality the Sun's ghostly corona appears — plasma at over a million degrees, hotter than the surface below it."),
    ("Auroras: how the Sun lights the polar skies", "https://en.wikipedia.org/wiki/Aurora",
     "Solar wind — a million-tonnes-per-second stream of charged particles — meets Earth's magnetic field and is funnelled toward the poles, where it excites atmospheric atoms: oxygen glows green at 100 km and deep red higher up, nitrogen adds purple edges. Jupiter, with a field 20,000 times stronger, produces auroras lit by its moon Io's volcanic sulphur, visible in X-rays. In September 1859 the Carrington Event hit: telegraph operators got shocks, lines sparked unattended, and auroras were seen from the Caribbean to Hawaii — the strongest solar storm on record."),
    ("Lunar laser ranging: we still bounce lasers off Apollo's mirrors", "https://en.wikipedia.org/wiki/Lunar_Laser_Ranging",
     "Astronauts left retroreflector arrays on the Moon in 1969 and 1971 — Apollo 11, 14 and 15 — and observatories still fire short laser pulses at them, catching the handful of photons that survive the round trip. The measurement is precise to a few centimetres from 384,000 km away, and it has been running for over 50 years. It confirms the Moon slides away at 3.8 cm a year (which is why days lengthen), tests general relativity's predictions about Earth-Moon motion, and shows how the Moon's orientation drifts — all from mirrors smaller than a suitcase."),
    ("TRAPPIST-1: seven Earth-size worlds around one small star", "https://en.wikipedia.org/wiki/TRAPPIST-1",
     "In 2016 a Belgian-led team found three Earth-size planets transiting TRAPPIST-1, a cool red dwarf 40 light-years away; in 2017 the count rose to seven — still the most planets ever found around a single star, with three in or near the habitable zone. The system is compact: all seven orbits fit well inside Mercury's. Tidal forces have almost certainly locked their rotation to the star, and JWST observations in 2023 showed planet b has no thick atmosphere at all, with the others' air still under debate — the best nearby laboratory for 'are rocky worlds breathable?'."),
    ("Bennu: the asteroid we brought a piece of home from", "https://en.wikipedia.org/wiki/101955_Bennu",
     "NASA's OSIRIS-REx touched asteroid Bennu for 4.9 seconds on 20 October 2020 and returned its sample capsule to the Utah desert on 24 September 2023, delivering 121.6 grams — more than double the mission's goal. Bennu is a rubble pile: a gravitationally-bound heap of rocks with as much empty space inside as a beach ball, and it is slowly spinning itself apart. It carries carbon and organics from the solar system's first 10 million years, and a 1-in-2,700 chance of hitting Earth on 24 September 2182 — the sample lets us know exactly what is coming if it ever does."),
    ("Cosmic microwave background: the baby picture of the universe", "https://en.wikipedia.org/wiki/Cosmic_microwave_background",
     "In 1965 Arno Penzias and Robert Wilson kept finding a faint hiss on their Bell Labs antenna that would not go away — anywhere they pointed. It was the afterglow of the Big Bang: light released when the universe cooled enough for atoms to form, about 380,000 years in, now stretched to 2.725 kelvin and filling the whole sky. Satellites COBE, WMAP and Planck mapped its temperature to one part in 100,000, and those tiny warm and cold patches — seeds too small to see at the time — grew into every galaxy that exists. Penzias and Wilson got the 2006 Nobel Prize."),
    ("Dark energy: the discovery that the universe is speeding up", "https://en.wikipedia.org/wiki/Dark_energy",
     "Two teams in 1998 compared distant Type Ia supernovae — cosmic lighthouses of known brightness — with how bright they should be, and found them dimmer than expected: not farther through curved space, but slowed down in their journey. The expansion of the universe, thought to be decelerating under gravity, was accelerating. Something makes up about 68% of the universe and pushes it apart; we call it dark energy and do not know what it is. The 2011 Nobel Prize went to Perlmutter, Schmidt and Riess for the measurement that broke cosmology."),
    ("Why the Sun shines: 100,000 years for light to escape", "https://en.wikipedia.org/wiki/Solar_core",
     "Fusion in the Sun's core converts about 4 million tonnes of matter into light every second via E=mc², at 15 million degrees. But a photon born there does not fly out: it travels microns before being absorbed and re-emitted in a new direction — a random walk that takes, by best estimates, 100,000-170,000 years to reach the surface. Once it does, the 8 minutes 20 seconds to Earth is a sprint. So the sunlight warming you today started its journey before agriculture — and emerged from a fog that thickens whenever the Sun's 'thermostat' misbehaves."),
    ("'Oumuamua: the first interstellar visitor", "https://en.wikipedia.org/wiki/'Oumuamua",
     "On 19 October 2017 Pan-STARRS in Hawaii caught a small object moving too fast to be bound by the Sun — the first interstellar visitor ever observed. It was tumbling, oddly flat, reddened, and outgassing just enough to curve its path without any visible comet tail: explanations ranged from a hydrogen-ice iceberg to a nitrogen-ice shard of a Pluto-like world 20 times farther out, none settled. Its name means 'scout' in Hawaiian. It also woke the sky surveys up: in July 2025 they caught 3I/ATLAS, the third confirmed interstellar object, on its way through."),
    ("Hubble Deep Field: how one blank patch of sky held 3,000 galaxies", "https://en.wikipedia.org/wiki/Hubble_Deep_Field",
     "In December 1995 Hubble stared at a speck of 'empty' sky near the Big Dipper for 10 consecutive days — an area a grain of sand held at arm's length covers — and came back with about 3,000 galaxies in various stages of a 12-billion-year history. The observation barely survived review: it consumed precious telescope time for a blank patch. Variants followed — the Ultra Deep Field, JWST's fields — and the same idea repeats: aim at nothing long enough, and the universe fills the frame with everything it has ever made."),
]

def main() -> int:
    ok = 0
    for title, url, summary in TOPICS:
        res = subprocess.run(
            [sys.executable, "-m", "ytauto", "discover", "--add", title,
             "--url", url, "--summary", summary],
            capture_output=True, text=True)
        line = (res.stdout or res.stderr).strip().splitlines()[-1] if (res.stdout or res.stderr) else ""
        print(("OK " if res.returncode == 0 else "XX "), line[:120])
        ok += res.returncode == 0
    print(f"\nseeded {ok}/{len(TOPICS)}")
    return 0 if ok == len(TOPICS) else 1

if __name__ == "__main__":
    sys.exit(main())
